    class BaseA:
        def method(self):
            pass
    class MiddleB(BaseA):
        def method(self):
            super().method()
    class TopC(MiddleB):
        def method(self):
            super().method()
    class BaseD:
        def other_method(self):
            pass
    class MiddleE(BaseD):
        def other_method(self):
            super().other_method()
    class TopF(MiddleE, BaseA):
        def other_method(self):
            super().other_method()
