    else:
        print(result1["details"])
    result2 = analyzer.compare_mros(TopF, TopC)
    print("\nComparison 2 (TopF vs TopC):")
    if "error_message" in result2:
        print(f"Error: {result2['error_message']}")
    else:
        print(result2["details"])
if __name__ == '__main__':
