import numpy as np
class DistributionComparator:
    def __init__(self):
        self.data_a = None
        self.data_b = None
    def load_data(self, data_a_list, data_b_list):
        try:
            self.data_a = np.array(data_a_list)
            self.data_b = np.array(data_b_list)
            if len(self.data_a) != len(self.data_b):
                raise ValueError("Both datasets must have the same number of samples.")
        except Exception as e:
            print(f"Error loading data: {e}")
    def compute_basic_stats(self, label="data"):
        if self.data_a is not None and label == "a":
            return {"mean": float(np.mean(self.data_a)), "std": float(np.std(self.data_a))}
        elif self.data_b is not None and label == "b":
            return {"mean": float(np.mean(self.data_b)), "std": float(np.std(self.data_b))}
    def compute_correlation_matrix(self):
        if len(self.data_a) != 0:
            corr = np.corrcoef([self.data_a, self.data_b])
            return {
                "corr_ab": float(corr[0][1]),
                "covariance_matrix": [float(x) for x in list(np.array(corr).flatten())]
            }
        else:
            raise ValueError("Data is empty.")
    def compute_kurtosis(self):
        if self.data_a is not None and self.data_b is not None:
            return {
                "kurtosis_a": float(np.kurtosis(self.data_a)),
                "kurtosis_b": float(np.kurtosis(self.data_b))
            }
    def compute_skewness(self):
        if self.data_a is not None and self.data_b is not None:
            return {
                "skewness_a": float(np.skew(self.data_a)),
                "skewness_b": float(np.skew(self.data_b))
            }
def main():
    dataset_a = [10, 25, 30, 45, 60]
    dataset_b = [8, 27, 32, 48, 62]
    comparator = DistributionComparator()
    try:
        comparator.load_data(dataset_a, dataset_b)
        print("=== Basic Statistics ===")
        stats_a = comparator.compute_basic_stats(label="a")
        stats_b = comparator.compute_basic_stats(label="b")
        print(f"Dataset A - Mean: {stats_a['mean']}, Std Dev: {stats_a['std']}")
        print(f"Dataset B - Mean: {stats_b['mean']}, Std Dev: {stats_b['std']}")
        print("\n=== Skewness Analysis ===")
        skew_data = comparator.compute_skewness()
        print(f"A Skewness: {skew_data['skewness_a']}")
        print(f"B Skewness: {skew_data['skewness_b']}")
        print("\n=== Kurtosis Analysis ===")
        kurt_data = comparator.compute_kurtosis()
        print(f"A Excess Kurtosis: {kurt_data['kurtosis_a']}")
        print(f"B Excess Kurtosis: {kurt_data['kurtosis_b']}")
        print("\n=== Correlation Analysis ===")
        corr_matrix = comparator.compute_correlation_matrix()
        print(f"Correlation Coefficient (A vs B): {corr_matrix['corr_ab']:.4f}")
    except Exception as e:
        print("Error during analysis:", str(e))
if __name__ == '__main__':
    main()

import numpy as np
class DistributionComparator:
    def __init__(self):
        self.data1 = None
        self.data2 = None
    def load_data(self, dataset_1: list, dataset_2: list) -> None:
        self.data1 = np.array(dataset_1, dtype=float)
        self.data2 = np.array(dataset_2, dtype=float)
    def compute_basic_stats(self) -> dict:
        stats = {}
        if len(self.data1.shape) == 0 or len(self.data2.shape) == 0:
            self.data1 = np.array([self.data1])
            self.data2 = np.array([self.data2])
        stats['mean_1'] = float(np.mean(self.data1))
        stats['std_1'] = float(np.std(self.data1, ddof=0))
        if len(self.data2.shape) == 0:
            self.data2 = np.array([self.data2])
        stats['mean_2'] = float(np.mean(self.data2))
        stats['std_2'] = float(np.std(self.data2, ddof=0))
        return stats
    def compute_correlation_matrix(self) -> dict:
        if len(self.data1.shape) == 0 or len(self.data2.shape) == 0:
            self.data1 = np.array([self.data1])
            self.data2 = np.array([self.data2])
        corr_matrix = {}
        flat_1 = self.data1.flatten() if self.data1.ndim > 1 else self.data1
        flat_2 = self.data2.flatten() if self.data2.ndim > 1 else self.data2
        if len(flat_1) != len(flat_2):
            raise ValueError("Datasets must have the same length for correlation calculation.")
        corr_matrix['pearson'] = float(np.corrcoef(flat_1, flat_2)[0, 1])
        return {k: v for k, v in corr_matrix.items() if not np.isnan(v)}
    def compute_distribution_metrics(self) -> dict:
        metrics = {}
        self.data1 = np.atleast_1d(np.asarray(self.data1))
        self.data2 = np.atleast_1d(np.asarray(self.data2))
        if len(self.data1) < 3 or len(self.data2) < 3:
            raise ValueError("Datasets must contain at least 3 elements for skewness/kurtosis.")
        metrics['skewness_1'] = float(np.skew(self.data1, bias=False))
        metrics['excess_kurtosis_1'] = float(np.kurtosis(self.data1, fisher=True, bias=False))
        if len(self.data2) >= 3:
            metrics['skewness_2'] = float(np.skew(self.data2, bias=False))
            metrics['excess_kurtosis_2'] = float(np.kurtosis(self.data2, fisher=True, bias=False))
        return {k: v for k, v in metrics.items() if not np.isnan(v)}
def main():
    dataset_a = [10.5, 12.3, 9.8, 11.2, 13.1, 10.9]
    dataset_b = [14.2, 16.7, 15.1, 17.3, 14.8, 16.2]
    comparator = DistributionComparator()
    try:
        assert len(dataset_a) == len(dataset_b), "Input datasets must have equal length."
        comparator.load_data(dataset_a, dataset_b)
        basic_stats = comparator.compute_basic_stats()
        distribution_metrics = comparator.compute_distribution_metrics()
        correlation_matrix = comparator.compute_correlation_matrix()
        print("=== Distribution Comparison Report ===")
        print(f"Dataset A: {dataset_a}")
        print(f"Dataset B: {dataset_b}")
        print("\n--- Basic Statistics ---")
        print(f"A Mean: {basic_stats['mean_1']:.4f}, Std Dev: {basic_stats['std_1']:.4f}")
        print(f"B Mean: {basic_stats['mean_2']:.4f}, Std Dev: {basic_stats['std_2']:.4f}")
        if 'pearson' in correlation_matrix:
            corr = correlation_matrix['pearson']
            label = "Strong" if abs(corr) > 0.7 else ("Moderate" if abs(corr) > 0.3 else "Weak")
            print(f"Pearson Correlation (A vs B): {corr:.4f} ({label})")
        print("\n--- Distribution Shape ---")
        for key, val in distribution_metrics.items():
            label = "Positive" if val > 0 else ("Negative" if val < 0 else "Zero")
            metric_name = f"{key.replace('_', ' ').title()}"
            print(f"{metric_name}: {val:.4f} ({label})")
    except Exception as e:
        print(f"Error during analysis: {e}")
if __name__ == '__main__':
    main()

import numpy as np
class DistributionComparator:
    def __init__(self):
        self.data_a = None
        self.data_b = None
    def load_data(self, data_list_a, data_list_b):
        try:
            arr_a = np.array(data_list_a)
            arr_b = np.array(data_list_b)
            if len(arr_a) == 0 or len(arr_b) == 0:
                raise ValueError("Datasets cannot be empty.")
            self.data_a = arr_a.astype(np.float64)
            self.data_b = arr_b.astype(np.float64)
        except Exception as e:
            raise RuntimeError(f"Failed to load data due to {e}")
    def compute_mean(self, dataset):
        return float(np.mean(dataset))
    def compute_variance(self, dataset):
        return float(np.var(dataset, ddof=0))
    def compute_std_deviation(self, dataset):
        var = self.compute_variance(dataset)
        return np.sqrt(var)
    def perform_t_test(self):
        n_a = len(self.data_a)
        n_b = len(self.data_b)
        mean_a = self.compute_mean(self.data_a)
        mean_b = self.compute_mean(self.data_b)
        var_pooled = ((n_a - 1) * np.var(self.data_a, ddof=0) + (n_b - 1) * np.var(self.data_b, ddof=0)) / (n_a + n_b - 2)
        se = np.sqrt(var_pooled * (1/n_a + 1/n_b))
        if se == 0:
            return {'t_statistic': float('inf'), 'p_value': 0.0, 'degrees_of_freedom': n_a + n_b - 2}
        t_val = abs(mean_a - mean_b) / se
        try:
            from scipy import stats as sp_stats
            df = n_a + n_b - 2
            two_tail_p = sp_stats.t.sf(t_val, df=df) * 2.0
            return {
                't_statistic': float(t_val), 
                'p_value': float(two_tail_p), 
                'degrees_of_freedom': int(df)
            }
        except ImportError:
            import math
            df = n_a + n_b - 2
            t_val_abs = abs(mean_a - mean_b) / se
            if t_val == 0.0 or np.isinf(t_val):
                return {'t_statistic': float('nan'), 'p_value': 1.0, 'degrees_of_freedom': int(df)}
            z_approx = t_val_abs / math.sqrt(2 * (df + 2)) 
            p_norm = 2 * (1 - self._approx_cdf(z_approx))
            return {
                't_statistic': float(t_val),
                'p_value': min(float(p_norm), 0.95),                                                 
                'degrees_of_freedom': int(df)
            }
    def _approx_cdf(self, x):
        return 0.5 * (1 + np.erf(x / math.sqrt(2)))
def main():
    dataset_a = [34, 67, 89, 12, 45, 78, 90, 11, 56, 33] * 1000
    dataset_b = [40, 65, 85, 15, 50, 75, 88, 20, 60, 35] * 1000
    comparator = DistributionComparator()
    try:
        comparator.load_data(dataset_a, dataset_b)
        stats_a = {
            'mean': comparator.compute_mean(comparator.data_a),
            'std_dev': comparator.compute_std_deviation(comparator.data_a),
            'variance': comparator.compute_variance(comparator.data_a)
        }
        stats_b = {
            'mean': comparator.compute_mean(comparator.data_b),
            'std_dev': comparator.compute_std_deviation(comparator.data_b),
            'variance': comparator.compute_variance(comparator.data_b)
        }
        t_test_result = comparator.perform_t_test()
        print("=== Statistical Distribution Comparison ===")
        print(f"Dataset A: Mean={stats_a['mean']:.2f}, Std Dev={stats_a['std_dev']:.2f}")
        print(f"Dataset B: Mean={stats_b['mean']:.2f}, Std Dev={stats_b['std_dev']:.2f}")
        if 't_statistic' in t_test_result and not np.isnan(t_test_result.get('t_statistic', 0)):
            print("\nT-Test Results:")
            print(f"T-statistic: {t_test_result['t_statistic']:.4f}")
            print(f"P-value (2-tailed): {t_test_result['p_value']:.6e}")
            print(f"Degrees of Freedom: {t_test_result['degrees_of_freedom']}")
        else:
            print("\nT-Test Results:")
            print("Could not compute valid t-statistic.")
    except Exception as e:
        print(f"Error during analysis: {e}")
if __name__ == '__main__':
    main()

import numpy as np
class DistributionComparator:
    def __init__(self):
        self.data_a = None
        self.data_b = None
    def load_data(self, a=None, b=None):
        if a is not None and b is not None:
            self.data_a = np.array(a)
            self.data_b = np.array(b)
    def analyze_distribution(self):
        if self.data_a is None or self.data_b is None:
            raise ValueError("Data must be loaded before analysis.")
        stats_a = {
            'mean': float(np.mean(self.data_a)),
            'median': float(np.median(self.data_a)),
            'std_dev': float(np.std(self.data_a, ddof=0)),
            'min_val': float(np.min(self.data_a)),
            'max_val': float(np.max(self.data_a))
        }
        stats_b = {
            'mean': float(np.mean(self.data_b)),
            'median': float(np.median(self.data_b)),
            'std_dev': float(np.std(self.data_b, ddof=0)),
            'min_val': float(np.min(self.data_b)),
            'max_val': float(np.max(self.data_b))
        }
        return stats_a, stats_b
    def compute_correlation_matrix(self):
        if self.data_a is None or self.data_b is None:
            raise ValueError("Data must be loaded before analysis.")
        corr = np.corrcoef(self.data_a.reshape(-1, 1), self.data_b.reshape(-1, 1))
        return float(corr[0][1]) if len(corr) > 1 else 0.0
    def generate_report(self):
        stats_a, stats_b = self.analyze_distribution()
        report_lines = [
            "Dataset A Statistics:",
            f"Mean: {stats_a['mean']:.4f}",
            f"Median: {stats_a['median']:.4f}",
            f"Std Deviation: {stats_a['std_dev']:.4f}",
            f"Range: [{stats_a['min_val']}, {stats_a['max_val']}]",
            "Dataset B Statistics:",
            f"Mean: {stats_b['mean']:.4f}",
            f"Median: {stats_b['median']:.4f}",
            f"Std Deviation: {stats_b['std_dev']:.4f}",
            f"Range: [{stats_b['min_val']}, {stats_b['max_val']}]",
            "Comparison Metrics:",
            f"Covariance Matrix Element (A, B): {self.compute_correlation_matrix():.4f}"
        ]
        return "\n".join(report_lines)
if __name__ == '__main__':
    sample_data_a = [10, 25, 30, 45, 60]
    sample_data_b = [8, 27, 32, 48, 59]
    comparator = DistributionComparator()
    try:
        comparator.load_data(sample_data_a, sample_data_b)
        report = comparator.generate_report()
        print(report)
        if len(comparator.data_a) > 1 and len(comparator.data_b) > 1:
            corr_val = float(np.corrcoef(comparator.data_a.reshape(-1, 1), comparator.data_b.reshape(-1, 1))[0][1])
            print(f"\nCorrelation Coefficient (Pearson): {corr_val:.4f}")
    except Exception as e:
        print(f"Error during analysis: {e}")

