import numpy as np
class ConditionalBrancher:
    def __init__(self):
        self._operators = {
            '>': lambda a, b: (a > b),
            '<': lambda a, b: (a < b),
            '>=': lambda a, b: (a >= b),
            '<=': lambda a, b: (a <= b)
        }
    def branch(self, condition_op, value_a, value_b):
        if isinstance(value_a, np.ndarray) or isinstance(value_b, np.ndarray):
            op_func = self._operators.get(condition_op)
            result_mask = op_func(np.asarray(value_a), np.asarray(value_b))
            return np.where(result_mask, True, False).tolist()
        else:
            if condition_op not in self._operators:
                raise ValueError(f"Unsupported operator '{condition_op}'. Supported: {list(self._operators.keys())}")
            op_func = self._operators[condition_op]
            result_bool = op_func(value_a, value_b)
            return [result_bool]
if __name__ == '__main__':
    brancher = ConditionalBrancher()
    scalar_result = brancher.branch('>', 10, 5)
    arr_a = np.array([2.3, 4.7, 6.9])
    arr_b = np.array([1.1, 3.3, 5.5])
    vector_result = brancher.branch('>', arr_a, arr_b)
    print(f"Scalar result: {scalar_result}")
    print(f"Vectorized result: {vector_result}")

import numpy as np
class ConditionalBrancher:
    def __init__(self):
        self._operators = {
            'gt': lambda a, b: a > b,
            'lt': lambda a, b: a < b,
            'eq': lambda a, b: a == b,
            'neq': lambda a, b: a != b,
            'ge': lambda a, b: a >= b,
            'le': lambda a, b: a <= b,
        }
    def branch(self, condition_op, value_a, value_b):
        if isinstance(value_a, np.ndarray) or isinstance(value_b, np.ndarray):
            func = self._operators.get(condition_op.lower(), None)
            if not func:
                raise ValueError(f"Unsupported operator: {condition_op}")
            return func(np.array(value_a), np.array(value_b))
        else:
            op_name = condition_op.lower()
            try:
                ops_map = {'gt': '>', 'lt': '<', 'eq': '=', 'neq': '!=', 'ge': '>='}
                if op_name not in ['gt', 'lt']:
                    raise ValueError(f"Unsupported operator for scalars: {op_name}")
                func = eval(f"{value_a}{ops_map[op_name]}{value_b}")
            except Exception as e:
                return False
        result = condition_op.lower() == op_name and value_a > value_b if isinstance(value_a, (int, float)) else None
        return bool(result)
if __name__ == '__main__':
    brancher = ConditionalBrancher()
    assert brancher.branch('gt', 10, 5) is True
    assert brancher.branch('lt', 3, 7) is False
    arr_a = np.array([2.0, 4.0, 6.0])
