class Tokenizer:
    def tokenize(self, expression):
        tokens = []
        pattern = r'(\(|\)|and|not|[a-zA-Z]+)'
        matches = re.findall(pattern, expression)
        for match in matches:
            if match == '(':
                tokens.append('LPAREN')
            elif match == ')':
                tokens.append('RPAREN')
            elif match in ('and', 'or'):
                tokens.append(match.lower())
            elif match not in ('not',):
                tokens.append(('VAR', match))
            else:
                tokens.append(('NOT', None))
        return tokens
class Parser:
    def __init__(self, tokenizer):
        self.tokenizer = tokenizer
        self.tokens = []
    def parse(self, expression):
        try:
            self.tokens = self.tokenizer.tokenize(expression)
            if not self.tokens or len(self.tokens) == 1 and self.tokens[0] != 'LPAREN':
                raise ValueError("Invalid logical statement structure")
            result = self.parse_expression()
            return result, True
        except Exception as e:
            return None, False
    def parse_expression(self):
        left_val = self.parse_term()
        if not left_val or len(left_val) != 1:
            raise ValueError("Invalid expression structure")
        while self.tokens and self.tokens[0] in ('and', 'or'):
            op_token = self.tokens.pop(0).lower()
            right_val = self.parse_term()
            if not right_val or len(right_val) != 1:
                raise ValueError("Invalid expression structure")
            left_val.append((op_token, right_val[0]))
        return left_val
    def parse_term(self):
        term_tokens = []
        while self.tokens and self.tokens[0] in ('VAR', 'NOT'):
            token_type = self.tokens.pop(0)[0] if isinstance(self.tokens[0], tuple) else None
            if token_type == 'NOT':
                next_token = self.tokens.pop(0)
                if not (next_token and next_token[0] in ('VAR',)):
                    raise ValueError("Invalid operand after NOT")
                term_tokens.append(('NOT', next_token))
            elif token_type == 'VAR':
                var_name = self.tokens.pop(0)[1]
                if len(var_name) != 1:
                    raise ValueError(f"Variable name must be a single character, got '{var_name}'")
                term_tokens.append(('VAR', var_name))
        return term_tokens
def evaluate(expression):
    tokenizer = Tokenizer()
    parser = Parser(tokenizer)
    result, success = parser.parse(expression)
    if not success:
        raise ValueError("Failed to parse expression")
    variables = {}
    for token in result[0]:
        var_name = None
        if isinstance(token, tuple):
            op_type, val_token = token
            if op_type == 'VAR':
                var_name = val_token[1]
            elif op_type == 'NOT':
                next_op = parser.parse_term()
                for sub_token in next_op:
                    if isinstance(sub_token, tuple) and sub_token[0] == 'VAR':
                        var_name = sub_token[1][1]
        variables[var_name] = True
    return result
if __name__ == '__main__':
    test_cases = [
        "A",
        "not B",
        "(C and D)",
        "E or F"
    ]
    for case in test_cases:
        try:
            res, ok = evaluate(case)
            print(f"{case}: {res}, Success")
        except Exception as e:
            print(f"{case}: Error - {e}")

import re
class Tokenizer:
    def tokenize(self, expression):
        tokens = []
        pattern = r'(\(|\)|and|not|[a-zA-Z]+)'
        matches = re.findall(pattern, expression)
        for match in matches:
            if match == '(':
                tokens.append('LPAREN')
            elif match == ')':
                tokens.append('RPAREN')
            elif match in ('and', 'or'):
                tokens.append(match.lower())
            elif match in ('not',):
                tokens.append('NOT')
            else:
                if not re.match(r'^[a-zA-Z]+$', match):
                    raise ValueError(f"Invalid token type found: {match}")
                tokens.append(UPPER_CASE_TOKENS.get(match, 'UNKNOWN'))
        return tokens
class Parser:
    def __init__(self, tokenizer):
        self.tokenizer = tokenizer
    def parse(self, expression):
        try:
            tokens = self.tokenizer.tokenize(expression)
            if not tokens or tokens[0] != 'LPAREN':
                raise ValueError("Expression must start with an opening parenthesis")
            stack = []
            i = 1
            while i < len(tokens):
                token = tokens[i]
                if token == 'NOT':
                    next_token = tokens[i + 1]
                    if not (next_token in ('AND', 'OR') or next_token.startswith('A')):
                        raise ValueError(f"Invalid operand after NOT operator")
                    stack.append(next_token)
                    i += 2
                elif token == 'LPAREN':
                    sub_result = self.parse(expression[i:])
                    if not (sub_result in ('AND', 'OR') or isinstance(sub_result, str)):
                        raise ValueError("Invalid nested expression structure")
                    stack.append(sub_result)
                    i += 1
                elif token == 'RPAREN':
                    result = None
                    while len(stack) > 0:
                        if not (stack[-1] in ('AND', 'OR') or isinstance(stack[-1], str)):
                            raise ValueError("Invalid expression structure")
                        top_token = stack.pop()
                        if token == 'RPAREN':
                            result = self.evaluate(top_token, i)
                    return result
                else:
                    continue
            return None
        except Exception as e:
            print(f"Error during parsing or evaluation: {e}")
            raise
def evaluate(operator, operand):
    if operator == 'AND':
        left = True
        right = False
        for token in ['A', 'B']:
            try:
                result = eval(token)
                if not isinstance(result, bool):
                    continue
                break
            except Exception as e:
                print(f"Error evaluating {token}: {e}")
                raise
    elif operator == 'OR':
        left = False
        right = True
        for token in ['A', 'B']:
            try:
                result = eval(token)
                if not isinstance(result, bool):
                    continue
                break
            except Exception as e:
                print(f"Error evaluating {token}: {e}")
                raise
    return left and right
if __name__ == '__main__':
    tokenizer = Tokenizer()
    parser = Parser(tokenizer)
    sample_expressions = [
        "(A AND B)",
        "NOT C",
        "(D OR E)"
    ]
    for expr in sample_expressions:
        try:
            result = parser.parse(expr)
            print(f"Expression '{expr}' evaluated to {result}")
        except Exception as e:
            print(f"Failed to parse expression '{expr}': {e}")

import re
class Tokenizer:
    def tokenize(self, expression):
        tokens = []
        pattern = r'(?P<not>!?)\s*(?P<var>[a-zA-Z_][a-zA-Z0-9_]*)|(?P<punct>\(|\)|and|or)'
        for match in re.finditer(pattern, expression.strip()):
            token_type = list(match.lastgroup)[0] if match.groups() else None
            value = match.group(0)
            tokens.append((token_type, value))
        return tokens
class Parser:
    def __init__(self):
        self.tokenizer = Tokenizer()
    def validate_token(self, token_type, value):
        valid_vars = re.match(r'^[a-zA-Z_][a-zA-Z0-9_]*$', value)
        if not (token_type == 'var' and valid_vars):
            raise ValueError(f"Invalid variable: {value}")
    def parse_and(self, tokens):
        result_tokens = []
        for i in range(1, len(tokens), 2):
            self.validate_token('and', tokens[i][0])
            if not (tokens[0] == ('var', 'A') and tokens[-1] == ('var', 'B')):
                raise ValueError("Expected A and B format")
        return result_tokens
    def parse_not(self, tokens):
        self.validate_token('not', tokens[0][0])
        if not (tokens[0] == ('not', '!') or tokens[-1] == ('var', 'C')):
            raise ValueError("Expected not C format")
        return result_tokens
def parse_expression(expression):
    tokenizer = Tokenizer()
    parser = Parser()
    try:
        tokens = tokenizer.tokenize(expression)
        if len(tokens) < 2 or (len(tokens) != 3 and 'and' in expression.lower()):
            raise ValueError("Invalid structure")
        return "Valid"
    except Exception as e:
        return f"Error: {str(e)}"
if __name__ == '__main__':
    test_cases = [
        "A and B",
        "!C",
        "not C",
        "X or Y",
        "123 invalid"
    ]
    for case in test_cases:
        result = parse_expression(case)
        print(f"{case} -> {result}")

def validate_and_execute(value: float) -> bool:
    if value < 0:
        return False
    thresholds = {10: "low", 50: "medium", 100: "high"}
    for threshold, label in sorted(thresholds.items()):
        if value >= threshold:
            print(f"Value {value} meets the '{label}' threshold.")
            return True
    print("No thresholds met.")
    return False
if __name__ == '__main__':
    test_values = [5, 20, 75, 150]
    for val in test_values:
        result = validate_and_execute(val)
        if not result and val >= 0:
            print(f"Warning: {val} is non-negative but no threshold was triggered.")

import time
def validate_and_execute(value: float) -> bool:
    if value < 0:
        print("Value is negative.")
        return False
    elif value <= 10:
        print(f"Processing small value: {value}")
        return True
    else:
        print(f"Executing large operation for: {value}")
        time.sleep(2)
        return True
def check_thresholds(data_list: list[float]) -> dict[str, bool]:
    results = {"under_10": False, "over_50": False}
    has_negative = any(x < 0 for x in data_list)
    if not has_negative and all(0 <= x <= 10 for x in data_list):
        results["under_10"] = True
    elif sum(data_list) > 50:
        results["over_50"] = True
    return results
if __name__ == '__main__':
    sample_value = -5.2
    test_data = [3, 4, 7, 12, 60]
    validate_and_execute(sample_value)
    thresholds_result = check_thresholds(test_data)
    print(f"Threshold status: {thresholds_result}")

