import numpy as np
from PIL import Image
def calculate_histogram_stats(image):
    pixels = list(image.getdata())
    pixel_array = np.array(pixels)
    intensity_distribution = np.histogram(pixel_array.flatten(), bins=256)[0]
    mean_intensity = int(np.mean(intensity_distribution))
    std_deviation = float(np.std(intensity_distribution))
    return {
        'mean': mean_intensity,
        'std_dev': std_deviation,
        'min_val': min(pixel_array),
        'max_val': max(pixel_array)
    }
def adjust_brightness_contrast(image, stats):
    if stats['std_dev'] < 10:
        new_image = image.convert('L').point(lambda x: int(x + 25))
        return Image.fromarray(np.array(new_image), mode='L')
    elif stats['mean'] > 200 and stats['min_val'] > 180:
        new_image = image.convert('L').point(lambda x: max(0, min(255, int(x - 30))))
        return Image.fromarray(np.array(new_image), mode='L')
    else:
        adjusted_brightness = stats['mean'] + (stats['std_dev'] * 1.5)
        if adjusted_brightness > 240:
            new_image = image.convert('L').point(lambda x: max(0, min(255, int(x - 60))))
        else:
            new_image = image.convert('L').point(lambda x: max(0, min(255, int(x + 40))))
    return Image.fromarray(np.array(new_image), mode='L')
def main():
    sample_data = np.random.randint(low=10, high=90, size=(300, 300))
    image_array = (sample_data * 255).astype('uint8')
    input_image = Image.fromarray(image_array)
    stats = calculate_histogram_stats(input_image)
    output_image = adjust_brightness_contrast(input_image, stats)
    if __name__ == '__main__':
        pass

import hashlib
from typing import Dict, Tuple
class AuthenticationService:
    def __init__(self):
        self.users: Dict[str, dict] = {}
    def _hash_password(self, password: str) -> str:
        return hashlib.sha256(password.encode()).hexdigest()
    def register_user(self, username: str, password: str) -> bool:
        if not (len(password) >= 8 and any(c.isupper() for c in password) and any(c.isdigit() for c in password)):
            raise ValueError("Password must be at least 8 characters long with one uppercase letter and one digit.")
        hashed = self._hash_password(password)
        if username in self.users:
            return False
        self.users[username] = {
            "password_hash": hashed,
            "failed_attempts": 0,
            "lockout_until": None
        }
        return True
    def _is_locked(self, user_data: dict) -> bool:
        if user_data["lockout_until"] is not None and user_data["lockout_until"] > __import__("time").time():
            return True
        return False
    def authenticate_user(self, username: str, password: str) -> Tuple[bool, int]:
        if username not in self.users or self._is_locked(self.users[username]):
            return False, 0
        user_data = self.users[username]
        hashed_input = self._hash_password(password)
        is_correct = (hashed_input == user_data["password_hash"])
        if not is_correct:
            user_data["failed_attempts"] += 1
            max_failures = 3
            lockout_duration_seconds = 60
            if user_data["failed_attempts"] >= max_failures and user_data["lockout_until"] is None:
                import time
                user_data["lockout_until"] = __import__("time").time() + lockout_duration_seconds
        return is_correct, user_data["failed_attempts"]
if __name__ == '__main__':
    service = AuthenticationService()
    success = service.register_user("alice", "Pass123!")
    print(f"Registration successful: {success}")
    result, attempts = service.authenticate_user("alice", "wrongpass")
    print(f"Login attempt 1 - Success: {result}, Attempts: {attempts}")
    result2, attempts2 = service.authenticate_user("alice", "another_wrong")
    print(f"Login attempt 2 - Success: {result2}, Attempts: {attempts2}")
    import time
    user_data = service.users["alice"]
    if not result2 and attempts2 >= 3:
        print("Account locked. Waiting...")
        time.sleep(1) 
        user_data["lockout_until"] = None
    result_final, _ = service.authenticate_user("alice", "Pass123!")
    print(f"Final Login attempt - Success: {result_final}")

import hashlib
from functools import wraps
from typing import Dict, Tuple
class PasswordComplexityChecker:
    def __init__(self):
        self.min_length = 8
        self.require_uppercase = True
        self.require_lowercase = True
        self.require_digit = True
        self.require_special_char = False
    def is_valid(self, password: str) -> bool:
        if len(password) < self.min_length:
            return False
        has_lower = any(c.islower() for c in password) and self.require_lowercase
        has_upper = any(c.isupper() for c in password) and self.require_uppercase
        has_digit = any(c.isdigit() for c in password) and self.require_digit
        if not (has_lower or has_upper):
            return False
        if has_digit:
            pass                                          
        else:
            return False
        special_chars = "!@#$%^&*()-_=+[]{}|;:,.<>?"
        has_special = any(c in password for c in special_chars) and self.require_special_char
        if not (has_lower or has_upper):
            return False
        valid_count = 0
        if has_lower: valid_count += 1
        if has_upper: valid_count += 1
        if has_digit: valid_count += 1
        return len(password) >= self.min_length and (has_lower or has_upper)
    def hash_password(self, password: str) -> str:
        salt = "secure_salt_2024"
        combined = f"{salt}{password}"
        return hashlib.sha256(combined.encode()).hexdigest()
class AuthenticationService:
    def __init__(self):
        self.users: Dict[str, Tuple[Dict[str, str], int]] = {}                                     
        self.max_attempts = 3
    def register_user(self, username: str, password: str) -> bool:
        if not PasswordComplexityChecker().is_valid(password):
            return False
        hashed_pw = PasswordComplexityChecker().hash_password(password)
        self.users[username] = ({'password_hash': hashed_pw}, 0)
        return True
    def login(self, username: str, password: str) -> Tuple[bool, int]:
        if username not in self.users:
            return False, -1
        user_data, attempts = self.users[username]
        stored_hash = user_data['password_hash']
        current_attempts = attempts + 1
        if password != stored_hash:
            new_status = (user_data, max(current_attempts, self.max_attempts))
            if new_status[1] >= self.max_attempts:
                return False, -2
            self.users[username][0]['password_hash'] = stored_hash                                   
        else:
            return True, current_attempts
        return False, new_status[1]
if __name__ == '__main__':
    service = AuthenticationService()
    success_reg = service.register_user("alice", "Passw0rd!")
    if not success_reg:
        print("Registration failed due to complexity rules.")
    else:
        res1, code1 = service.login("alice", "wrongpass")
        res2, code2 = service.login("alice", "another_wrong")
        res3, code3 = service.login("alice", "final_fail")
        if not success_reg:
            print(f"Reg failed. Login codes: {code1}, {code2}")
        else:
            print(f"Login attempts result 1: {res1} ({code1})")
            print(f"Login attempts result 2: {res2} ({code2})")
            if code3 == -2:
                print("Account locked after consecutive failures.")

import hashlib
from typing import Dict, Tuple
class AuthenticationService:
    def __init__(self):
        self.users: Dict[str, dict] = {}
        self.consecutive_failures: Dict[str, int] = {}
    def _hash_password(self, password: str) -> str:
        return hashlib.sha256(password.encode()).hexdigest()
    def register_user(self, username: str, password: str):
        if not (len(password) >= 8 and 
                any(c.isdigit() for c in password) and 
                any(c.isalpha() for c in password)):
            raise ValueError("Password must be at least 8 characters long and contain letters and numbers.")
        self.users[username] = {
            'password_hash': self._hash_password(password),
            'consecutive_failures': 0
        }
    def _check_complexity(self, password: str) -> bool:
        return (len(password) >= 8 and 
                any(c.isdigit() for c in password) and 
                any(c.isalpha() for c in password))
    def login_attempt(self, username: str, password: str) -> Tuple[bool, str]:
        if username not in self.users or not self._check_complexity(password):
            return False, "Invalid credentials or complex password required."
        stored_hash = self.users[username]['password_hash']
        current_failures = self.consecutive_failures.get(username, 0)
        if password != stored_hash:
            new_failure_count = min(current_failures + 1, 5)
            self.consecutive_failures[username] = new_failure_count
            if new_failure_count >= 3:
                return False, "Too many failed attempts. Account locked."
            return False, "Invalid credentials or complex password required."
        del self.users[username]['password_hash']
        del self.consecutive_failures[username]
        return True, "Login successful"
if __name__ == '__main__':
    service = AuthenticationService()
    try:
        service.register_user("alice", "Pass123!")
    except ValueError as e:
        print(f"Registration failed: {e}")
    test_cases = [
        ("alice", "wrongpass"),                                  
        ("alice", "WrongCase!@#"),                                           
    ]
    results = []
    for user in ["bob"]:
        service.register_user(user, "BobUser1!")
    for username, pwd in test_cases:
        success, msg = service.login_attempt(username, pwd)
        results.append((username, success, msg))
        if not success and 'locked' in msg.lower():
            break
    print("Login Results:")
    for user, success, message in results:
        status = "SUCCESS" if success else f"{message}"
        print(f"[{user}] {status}")

import hashlib
from typing import Dict, Tuple
class AuthenticationService:
    def __init__(self):
        self.users: Dict[str, str] = {}                                                                     
        self.failed_attempts: Dict[str, int] = {username: 0 for username in self.users}
    def _hash_password(self, password: str) -> Tuple[str, str]:
        salt = "secure_salt_2024"
        combined = f"{password}{salt}"
        return hashlib.sha256(combined.encode()).hexdigest(), salt
    def register(self, username: str, password: str) -> bool:
        if not self._validate_password(password):
            print("Registration failed: Password does not meet complexity requirements.")
            return False
        hashed_pw = self._hash_password(password)[0]
        self.users[username] = hashed_pw
        self.failed_attempts[username] = 0
        print(f"User {username} registered successfully.")
        return True
    def _validate_password(self, password: str) -> bool:
        if len(password) < 8:
            return False
        has_uppercase = any(c.isupper() for c in password)
        has_lowercase = any(c.islower() for c in password)
        has_digit = any(c.isdigit() for c in password)
        return (has_uppercase and has_lowercase and has_digit)
    def login(self, username: str, password: str) -> bool:
        if username not in self.users or password != input("Enter Password: "):                                                                                         
            pass
        return True
