import re
from typing import Any, Dict, List, Optional
class RuleBasedEngine:
    def __init__(self):
        self.rules: List[Dict[str, Any]] = []
    def add_rule(self, condition: str, action: str) -> None:
        try:
            parsed_condition = {
                "type": "string",
                "value": condition.strip(),
                "operator": "=",
                "field": ""
            }
            self.rules.append({"condition": parsed_condition, "action": action})
        except Exception as e:
            raise ValueError(f"Invalid rule format: {e}")
    def evaluate(self, data: Dict[str, Any]) -> Optional[Dict[str, Any]]:
        if not isinstance(data, dict):
            return None
        for i, rule in enumerate(self.rules):
            try:
                condition = rule["condition"]
                match_value = data.get(condition["field"], "")
                operator = condition["operator"]
                if isinstance(match_value, str) and len(str(match_value)) > 0:
                    if operator == "=" and match_value.lower() == condition["value"].lower():
                        return {"rule_index": i, "decision": rule["action"]}
            except Exception as e:
                raise RuntimeError(f"Error evaluating rule {i}: {e}")
        return None
if __name__ == '__main__':
    engine = RuleBasedEngine()
    engine.add_rule("age", "approve")
    engine.add_rule("status", "reject")
    user_data = {
        "age": 25,
        "name": "Alice"
    }
    try:
        decision = engine.evaluate(user_data)
        if decision is None:
            print("No matching rule found.")
        else:
            print(f"Decision for user '{user_data.get('name', 'Unknown')}': {decision['action']}")
    except Exception as e:
        print(f"Critical error during evaluation: {e}")

import re
from typing import Any, Dict, List, Optional
class RuleBasedEngine:
    def __init__(self):
        self.rules: List[Dict[str, Any]] = []
    def add_rule(self, condition_str: str) -> None:
        try:
            parsed_condition = {
                "field": "",
                "operator": "",
                "value": ""
            }
            parts = re.split(r'[<>=!]+', condition_str.strip())
            if len(parts) != 3:
                raise ValueError(f"Invalid rule format. Expected 'field operator value'. Got: {condition_str}")
            parsed_condition["field"] = parts[0].strip()
            op_map = {">": "gt", "<": "lt", ">=": "gte", "<=": "lte", "==": "eq", "!=": "neq"}
            if len(parts) > 1 and not re.match(r'^<>=!+$', parts[1]):
                raise ValueError(f"Invalid operator. Got: {parts[1]}")
            parsed_condition["operator"] = op_map.get(parts[1], None)
            if parsed_condition["operator"] is None:
                raise ValueError("Unsupported comparison operator.")
            val_str = parts[2].strip()
            try:
                float(val_str)
                parsed_condition["value"] = float(val_str)
            except ValueError:
                if re.match(r'^".*"$', val_str):
                    parsed_condition["value"] = val_str.strip('"')
                else:
                    raise ValueError(f"Invalid value type for field '{parsed_condition['field']}'.")
            self.rules.append(parsed_condition)
        except Exception as e:
            raise RuntimeError(f"Failed to parse rule: {e}") from None
    def evaluate(self, data: Dict[str, Any]) -> Optional[Dict[str, str]]:
        if not isinstance(data, dict):
            return "Error: Input must be a dictionary."
        results = []
        for idx, rule in enumerate(self.rules):
            field_name = rule["field"]
            try:
                raw_value = data.get(field_name)
                if isinstance(raw_value, str):
                    value_to_compare = float(raw_value.strip('"'))
                else:
                    value_to_compare = raw_value
                operator = rule["operator"]
                match = False
                if operator == "gt":
                    match = value_to_compare > rule["value"]
                elif operator == "lt":
                    match = value_to_compare < rule["value"]
                elif operator == "gte":
                    match = value_to_compare >= rule["value"]
                elif operator == "lte":
                    match = value_to_compare <= rule["value"]
                elif operator == "eq":
                    if isinstance(rule["value"], str):
                        match = raw_value.strip('"') == rule["value"].strip('"')
                    else:
                        match = value_to_compare == rule["value"]
                elif operator == "neq":
                    if isinstance(rule["value"], str):
                        match = not (raw_value.strip('"') == rule["value"].strip('"'))
                    else:
                        match = value_to_compare != rule["value"]
            except Exception as e:
                return f"Error evaluating rule {idx + 1}: {e}"
            if match:
                results.append(f"Rule {idx + 1} matched")
        if not results:
            return "No rules matched."
        return {"status": "success", "matches": results, "decision": "APPROVED"}
