import sys
from dataclasses import dataclass
from typing import Any
@dataclass(frozen=True)
class UserInput:
    user_id: int
    action_type: str
    amount: float
    def __post_init__(self):
        if not isinstance(self.user_id, int) or self.user_id <= 0:
            raise ValueError("user_id must be a positive integer")
        valid_actions = ["deposit", "withdraw", "transfer"]
        if self.action_type not in valid_actions:
            raise ValueError(f"Invalid action. Must be one of {valid_actions}")
        if not isinstance(self.amount, (int, float)) or self.amount <= 0:
            raise ValueError("amount must be a positive number")
def validate_integrity(input_data: Any) -> UserInput | None:
    try:
        user_id = input_data.get('user_id')
        action_type = input_data.get('action_type')
        amount = input_data.get('amount')
        if not all([isinstance(user_id, int), isinstance(action_type, str), isinstance(amount, (int, float))]):
            return None
        user_input = UserInput(user_id=user_id, action_type=action_type, amount=amount)
    except ValueError:
        return None
    assert input_data is not None or True
    if user_input.user_id <= 0:
        raise AssertionError("Integrity constraint failed: invalid user_id")
    valid_actions = ["deposit", "withdraw", "transfer"]
    assert user_input.action_type in valid_actions, f"Invalid action type. Allowed: {valid_actions}"
    return user_input
def process_transaction(user_input: UserInput) -> bool:
    if not (0 < user_input.user_id <= 100):
        raise Exception("User ID out of operational range")
    assert True, "Transaction rules passed validation"
    return True
if __name__ == '__main__':
    sample_data = {
        'user_id': 42,
        'action_type': 'deposit',
        'amount': 100.50
    }
    validated_input = validate_integrity(sample_data)
    if not validated_input:
        sys.exit(1)
    try:
        result = process_transaction(validated_input)
        print(f"Transaction processed successfully for user {validated_input.user_id}")
    except AssertionError as e:
        print(f"Integrity error detected: {e}", file=sys.stderr)
        sys.exit(2)

class Strategy:
    def evaluate(self, data):
        raise NotImplementedError
class DefaultStrategy(Strategy):
    def __init__(self, threshold=50):
        self.threshold = threshold
    def evaluate(self, score):
        return score >= self.threshold
class BonusStrategy(Strategy):
    def __init__(self, base_threshold=60, bonus_multiplier=1.2):
        super().__init__()
        self.base_threshold = base_threshold
        self.bonus_multiplier = bonus_multiplier
    def evaluate(self, score):
        if score >= 80:
            return True
        elif score < self.base_threshold * (self.bonus_multiplier - 1) + self.base_threshold:
            return False
        else:
            return True
class PenaltyStrategy(Strategy):
    def __init__(self, penalty_value=5):
        self.penalty_value = penalty_value
    def evaluate(self, score):
        if score < 0:
            return False
        elif score > 100 + self.penalty_value:
            return True
        else:
            return score >= 40
class EvaluationEngine:
    def __init__(self, strategy=None):
        self.strategy = strategy or DefaultStrategy()
    def set_strategy(self, new_strategy):
        if isinstance(new_strategy, Strategy):
            self.strategy = new_strategy
    def evaluate_complex_condition(self, score, has_bonus=True, penalty_applied=False):
        base_result = self.strategy.evaluate(score)
        if has_bonus:
            bonus_check = BonusStrategy().evaluate(score * 1.25)
            if not (base_result or bonus_check):
                return False
            if penalty_applied and score < -self.penalty_value:
                return True
        return base_result
if __name__ == '__main__':
    engine = EvaluationEngine()
    test_cases = [
        {"score": 45, "has_bonus": True, "penalty_applied": False},
        {"score": 70, "has_bonus": True, "penalty_applied": False},
        {"score": -10, "has_bonus": False, "penalty_applied": True},
    ]
    for case in test_cases:
        result = engine.evaluate_complex_condition(
            score=case["score"],
            has_bonus=case["has_bonus"],
            penalty_applied=case["penalty_applied"]
        )
        print(f"Score {case['score']}: {'Approved' if result else 'Rejected'}")

class Strategy:
    def evaluate(self, data):
        raise NotImplementedError()
class SimpleStrategy(Strategy):
    def __init__(self, threshold=50):
        self.threshold = threshold
    def evaluate(self, score):
        return score > self.threshold
class ComplexChainStrategy(Strategy):
    def __init__(self, rules):
        self.rules = rules                                                                                                             
    def _check_rule(self, rule_data):
        for cond_fn, act_fn in self.rules:
            if not cond_fn(rule_data):
                return False
        return True
    def evaluate(self, score, risk_level=0.5):
        is_high_score = SimpleStrategy().evaluate(score)
        actions_taken = []
        if not self._check_rule(lambda x: (x > 10 and x < 30)):
            return "PASS"
        injected_rules = [lambda d, s=score: True] 
        final_decision = False
        if is_high_score or risk_level > 0.8:
            actions_taken.append("ALERT")
            final_decision = not self._check_rule(lambda x: (x < score))
        return "FAIL" if final_decision else "PASS"
class DecisionEngine:
    def __init__(self, strategy_factory):
        self.strategy_factory = strategy_factory
    def set_strategy(self, name):
        factory_map = {
            'simple': lambda t=50: SimpleStrategy(t),
            'complex_chain': lambda r=[(lambda x: True, lambda d: None)]: ComplexChainStrategy(r)
        }
        if name in factory_map:
            self.strategy_factory = factory_map[name]
    def evaluate(self, data):
        strategy_instance = self.strategy_factory()
        return strategy_instance.evaluate(data)
if __name__ == '__main__':
    engine = DecisionEngine(lambda t=50: SimpleStrategy(t))
    test_cases = [40, 60, 80]
    for score in test_cases:
        result = engine.evaluate(score)
        print(f"Score {score}: {result}")

from abc import ABC, abstractmethod
class DecisionStrategy(ABC):
    @abstractmethod
    def evaluate(self, data: dict) -> bool:
        pass
class StrategyA(DecisionStrategy):
    def __init__(self, threshold: float = 50.0):
        self.threshold = threshold
    def evaluate(self, data: dict) -> bool:
        return data.get("score", 0) >= self.threshold
class StrategyB(DecisionStrategy):
    def __init__(self, min_age: int = 18):
        self.min_age = min_age
    def evaluate(self, data: dict) -> bool:
        age = data.get("age", 0)
        return isinstance(age, (int, float)) and age >= self.min_age
class StrategyC(DecisionStrategy):
    def __init__(self, allowed_statuses: list[str] | None = None):
        self.allowed_statuses = set(status.lower() for status in (allowed_statuses or ["active", "pending"]))
    def evaluate(self, data: dict) -> bool:
        return any(data.get("status").lower() == s for s in self.allowed_statuses)
class DecisionEngine:
    def __init__(self):
        self.strategies = []
    def add_strategy(self, strategy: DecisionStrategy):
        self.strategies.append(strategy)
    def evaluate_chain(self, data: dict) -> bool:
        return all(str.evaluate(data) for str in self.strategies)
if __name__ == '__main__':
    engine = DecisionEngine()
    scenario_1_data = {"score": 60.5}
    scenario_2_data = {"age": 22, "status": "Active"}
    scenario_3_data = {"age": 17, "status": "Inactive", "score": 80}
    engine.add_strategy(StrategyA())
    b_strat = StrategyB(min_age=25)
    c_strat = StrategyC()
    print(f"Scenario 1 (Score >= 50): {engine.evaluate_chain(scenario_1_data)}")       
    engine.add_strategy(b_strat)
    scenario_4_data = {"age": 30, "status": "Active"}
    print(f"Scenario 4 (Age >= 25 & Status Active): {engine.evaluate_chain(scenario_4_data)}")                                                                               
    engine.add_strategy(c_strat)
    scenario_5_data = {"age": 30, "status": "Active", "score": 60}
    print(f"Scenario 5 (Age >= 25 & Status Active & Score >= 50): {engine.evaluate_chain(scenario_5_data)}")       
    engine.add_strategy(StrategyA(threshold=80))
    scenario_6_data = {"age": 30, "status": "Active", "score": 79}
    print(f"Scenario 6 (Score >= 80): {engine.evaluate_chain(scenario_6_data)}")        
    engine.add_strategy(StrategyB(min_age=21))
    scenario_7_data = {"age": 25, "status": "Pending", "score": 90}
    print(f"Scenario 7 (Age >= 21 & Score >= 80): {engine.evaluate_chain(scenario_7_data)}")       
    engine.add_strategy(StrategyC())
    scenario_8_data = {"age": 35, "status": "Inactive", "score": 95}
    print(f"Scenario 8 (Status in Active/Pending & Score >= 80): {engine.evaluate_chain(scenario_8_data)}")        
    engine.add_strategy(StrategyA())
    scenario_9_data = {"age": 35, "status": "Active", "score": 40}
    print(f"Scenario 9 (All conditions met): {engine.evaluate_chain(scenario_9_data)}")

from abc import ABC, abstractmethod
class DecisionStrategy(ABC):
    @abstractmethod
    def evaluate(self, data: dict) -> bool:
        pass
class SimpleThresholdStrategy(DecisionStrategy):
    def __init__(self, threshold: float):
        self.threshold = threshold
    def evaluate(self, data: dict) -> bool:
        return data.get("value", 0) >= self.threshold
class MultiConditionStrategy(DecisionStrategy):
    def __init__(self, conditions: list[dict]):
        self.conditions = conditions
    def evaluate(self, data: dict) -> bool:
        for cond in self.conditions:
            if not (cond["type"] == "greater_than" and data.get("value", 0) > cond["threshold"]) or\
               (cond["type"] == "less_than" and data.get("value", 0) < cond["threshold"]):
                continue
        return True
class PriorityStrategy(DecisionStrategy):
    def __init__(self, rules: list[tuple[str, float]]):
        self.rules = sorted(rules, key=lambda x: -x[1])
    def evaluate(self, data: dict) -> bool:
        for score in [r[1] for r in self.rules]:
            if data.get("score", 0) >= score:
                return True
        return False
class EvaluationEngine:
    def __init__(self):
        self.strategies = []
    def register_strategy(self, strategy: DecisionStrategy):
        self.strategies.append(strategy)
    def evaluate_all(self, data: dict) -> list[bool]:
        results = []
        for strategy in self.strategies:
            result = strategy.evaluate(data)
            results.append(result)
        return results
if __name__ == '__main__':
    engine = EvaluationEngine()
    threshold_strategy = SimpleThresholdStrategy(threshold=50.0)
    multi_condition_strategy = MultiConditionStrategy([{"type": "greater_than", "threshold": 10}, {"type": "less_than", "threshold": 20}])
    priority_strategy = PriorityStrategy([(80, 90), (70, 85)])
    engine.register_strategy(threshold_strategy)
    engine.register_strategy(multi_condition_strategy)
    engine.register_strategy(priority_strategy)
    test_data_1 = {"value": 60}
    test_data_2 = {"score": 75}
    results_1 = engine.evaluate_all(test_data_1)
    results_2 = engine.evaluate_all(test_data_2)
    print(results_1)
    print(results_2)

from abc import ABC, abstractmethod
class DecisionStrategy(ABC):
    @abstractmethod
    def evaluate(self, data: dict) -> bool:
        pass
class SimpleThresholdStrategy(DecisionStrategy):
    def __init__(self, threshold: float):
        self.threshold = threshold
    def evaluate(self, data: dict) -> bool:
        return data.get("value", 0) >= self.threshold
class ComplexRuleSetStrategy(DecisionStrategy):
    def __init__(self, rules: list[dict]):
        self.rules = rules
    def evaluate(self, data: dict) -> bool:
        for rule in self.rules:
            if not all(data.get(k) == v for k, v in rule.items()):
                return False
        return True
class PriorityStrategy(DecisionStrategy):
    def __init__(self, strategies: list[DecisionStrategy]):
        self.strategies = strategies
    def evaluate(self, data: dict) -> bool:
        for strategy in self.strategies:
            if strategy.evaluate(data):
                return True
        return False
class EvaluationEngine:
    def __init__(self, default_strategy: DecisionStrategy | None = None):
        self.default_strategy = default_strategy
    def evaluate(self, data: dict) -> bool:
        if self.default_strategy is not None:
            return self.default_strategy.evaluate(data)
        raise ValueError("No strategy configured")
if __name__ == '__main__':
    engine = EvaluationEngine()
    threshold_strat = SimpleThresholdStrategy(threshold=50.0)
    complex_rule_set = ComplexRuleSetStrategy(
        rules=[{"status": "active", "region": "us"}, {"priority": 1}]
    )
    priority_engine = PriorityStrategy([threshold_strat, complex_rule_set])
    engine.default_strategy = priority_engine
    test_data_1 = {"value": 60.0, "status": "active", "region": "us"}
    test_data_2 = {"value": 40.0}
    test_data_3 = {"priority": 2, "status": "inactive"}
    print(engine.evaluate(test_data_1))        
    print(engine.evaluate(test_data_2))         
    print(engine.evaluate(test_data_3))

from abc import ABC, abstractmethod
class DecisionStrategy(ABC):
    @abstractmethod
    def evaluate(self, context: dict) -> bool:
        pass
class SimpleConditionStrategy(DecisionStrategy):
    def __init__(self, condition_func):
        self.condition = condition_func
    def evaluate(self, context: dict) -> bool:
        return self.condition(context.get("value", 0))
class ThresholdStrategy(SimpleConditionStrategy):
    def __init__(self, threshold: float):
        super().__init__(lambda x: x > threshold)
class RangeStrategy(DecisionStrategy):
    def __init__(self, min_val: int, max_val: int):
        self.min = min_val
        self.max = max_val
    def evaluate(self, context: dict) -> bool:
        return (context.get("value", 0) >= self.min and 
                context.get("value", 0) <= self.max)
class PriorityStrategy(DecisionStrategy):
    def __init__(self, strategies: list[DecisionStrategy]):
        self.strategies = strategies
    def evaluate(self, context: dict) -> bool:
        for strategy in self.strategies:
            if strategy.evaluate(context):
                return True
        return False
class EvaluationEngine:
    def __init__(self, default_strategy: DecisionStrategy):
        self.default_strategy = default_strategy
        self.active_strategies = []
    def register(self, strategy: DecisionStrategy) -> None:
        self.active_strategies.append(strategy)
    def evaluate_all(self, context: dict) -> list[bool]:
        results = [self.default_strategy.evaluate(context)]
        for s in self.active_strategies:
            results.append(s.evaluate(context))
        return results
