import json
import logging
from pathlib import Path
from typing import Dict, Any, List, Callable
from dataclasses import dataclass
from enum import Enum
class RuleType(Enum):
    CONDITION = "condition"
    ACTION = "action"
@dataclass(frozen=True)
class DecisionRule:
    rule_id: str
    rule_type: RuleType
    payload: Dict[str, Any]
    def matches(self, context: Dict[str, Any]) -> bool:
        for key, value in self.payload.items():
            if isinstance(value, list):
                return any(context.get(key) == item for item in value)
            elif callable(value):
                result = value()
                return (context.get(key) is None and not result) or context.get(key) != result
            else:
                return context.get(key) == value
class DecisionEngine:
    def __init__(self, config_path: str, log_level: int = logging.DEBUG):
        self.rules: List[DecisionRule] = []
        self.logger = logging.getLogger(__name__)
        self.logger.setLevel(log_level)
        handler = logging.StreamHandler()
        formatter = logging.Formatter('%(asctime)s - %(levelname)s - %(message)s')
        handler.setFormatter(formatter)
        self.logger.addHandler(handler)
        if Path(config_path).exists():
            with open(config_path, 'r', encoding='utf-8') as f:
                config_data = json.load(f)
            for item in config_data.get('rules', []):
                rule_type_map = {RuleType.CONDITION.value: RuleType.CONDITION, 
                                RuleType.ACTION.value: RuleType.ACTION}
                if 'type' not in item or item['type'] not in rule_type_map:
                    self.logger.error(f"Invalid rule type for ID '{item.get('rule_id')}'. Skipping.")
                    continue
                try:
                    payload = json.loads(item.get('payload', '{}'))
                    decision_rule = DecisionRule(
                        rule_id=item['rule_id'],
                        rule_type=rule_type_map[item['type']],
                        payload=payload
                    )
                    self.rules.append(decision_rule)
                    self.logger.info(f"Loaded rule: {decision_rule.rule_id}")
                except json.JSONDecodeError as e:
                    self.logger.error(f"JSON decode error for ID '{item.get('rule_id')}': {e}")
    def evaluate(self, context: Dict[str, Any]) -> List[DecisionRule]:
        matched_rules = []
        if not self.rules:
            return matched_rules
        sorted_rules = sorted(self.rules, key=lambda r: r.rule_id)
        for rule in sorted_rules:
            try:
                is_match = False
                if rule.rule_type == RuleType.CONDITION and not isinstance(rule.payload.get('action'), list):
                    is_match = rule.matches(context)
                elif rule.rule_type == RuleType.ACTION:
                    if 'condition' in rule.payload:
                        cond_payload = json.loads(rule.payload['condition'])
                        is_match = any(cond_payload.get(k, True) for k in ['context'] if isinstance(cond_payload[k], list))
                matched_rules.append(rule)
            except Exception as e:
                self.logger.error(f"Error evaluating rule {rule.rule_id}: {e}")
        return matched_rules
if __name__ == '__main__':
    config_file = 'decision_config.json'
    engine = DecisionEngine(config_path=config_file, log_level=logging.INFO)
    test_context = {"user_age": 25, "is_vip": True}
    results = engine.evaluate(test_context)
    print(f"Evaluated {len(results)} rules.")
    for rule in results:
        self.logger.info(f"Matched Rule ID: {rule.rule_id}")

import json
import logging
from pathlib import Path
from dataclasses import dataclass
from typing import Dict, Any, List, Callable
logging.basicConfig(level=logging.DEBUG)
logger = logging.getLogger(__name__)
@dataclass(frozen=True)
class Rule:
    name: str
    condition: Callable[[Any], bool]
    action: Callable[[], Any]
def load_rules_from_config(config_path: Path) -> List[Rule]:
    if not config_path.exists():
        logger.error(f"Configuration file not found: {config_path}")
        return []
    try:
        with open(config_path, 'r') as f:
            data = json.load(f)
        rules = []
        for item in data.get('rules', []):
            if isinstance(item, dict) and 'name' in item and 'condition' in item and 'action' in item:
                cond_str = str(item['condition'])
                act_str = str(item['action'])
                try:
                    condition_func = eval(cond_str)
                    action_func = eval(act_str)
                    rule = Rule(
                        name=item.get('name', f"rule_{len(rules)+1}"),
                        condition=condition_func,
                        action=action_func
                    )
                    rules.append(rule)
                except Exception as e:
                    logger.error(f"Failed to parse rule '{item.get('name')}': {e}")
        return rules
    except json.JSONDecodeError as je:
        logger.error(f"Invalid JSON in configuration file: {je}")
        raise
def evaluate_rules(data: Any, rules: List[Rule]) -> Dict[str, Any]:
    results = {}
    for rule in rules:
        try:
            if rule.condition(data):
                result_data = rule.action()
                logger.debug(f"Rule '{rule.name}' triggered. Result: {result_data}")
                results[f"{rule.name}_action"] = result_data
            else:
                logger.info(f"Rule '{rule.name}' condition not met.")
        except Exception as e:
            logger.error(f"Error executing rule '{rule.name}': {e}")
    return results
if __name__ == '__main__':
    config_path = Path('config.json')
    try:
        rules = load_rules_from_config(config_path)
        sample_data = {"user_age": 25, "is_admin": False}
        final_results = evaluate_rules(sample_data, rules)
        logger.info(f"Final Decision Results: {final_results}")
    except Exception as e:
        logger.critical(f"FATAL ERROR in decision framework initialization: {e}", exc_info=True)

import json
import logging
from pathlib import Path
from typing import Dict, Any, List, Callable, Optional
class RuleEngine:
    def __init__(self, config_path: str):
        self.rules: Dict[str, Dict[str, Any]] = {}
        self.logger = logging.getLogger(__name__)
        handler = logging.StreamHandler()
        formatter = logging.Formatter('%(asctime)s - %(levelname)s - %(message)s')
        handler.setFormatter(formatter)
        self.logger.addHandler(handler)
        self.logger.setLevel(logging.DEBUG)
    def load_rules(self, config_path: str):
        try:
            with open(config_path, 'r', encoding='utf-8') as f:
                raw_config = json.load(f)
            if not isinstance(raw_config, dict):
                raise ValueError("Configuration must be a dictionary.")
            self.rules = {}
            for rule_id, condition in raw_config.items():
                try:
                    if 'condition' not in condition or 'action' not in condition:
                        raise KeyError(f"Rule '{rule_id}' missing required keys 'condition' and/or 'action'.")
                    self.rules[rule_id] = {
                        "id": rule_id,
                        "condition": condition["condition"],
                        "action": condition["action"]
                    }
                except Exception as e:
                    self.logger.error(f"Failed to parse rule '{rule_id}': {str(e)}")
            if not self.rules:
                raise ValueError("No valid rules loaded.")
            self.logger.info(f"Successfully loaded {len(self.rules)} rules from {config_path}")
        except FileNotFoundError:
            self.logger.critical(f"Configuration file not found: {config_path}")
            raise
        except json.JSONDecodeError as e:
            self.logger.critical(f"Invalid JSON in configuration file: {str(e)}")
            raise
    def evaluate(self, data: Dict[str, Any]) -> Optional[Dict[str, str]]:
        for rule_id, rule_data in self.rules.items():
            condition = rule_data["condition"]
            try:
                if isinstance(condition, dict):
                    match = True
                    for field, expected_value in condition.items():
                        actual_value = data.get(field)
                        if actual_value != expected_value:
                            match = False
                            break
                elif isinstance(condition, list):
                    match = True
                    for item in condition:
                        if not item or item is None:
                            match = False
                            break
                else:
                    raise ValueError(f"Unsupported condition type for rule '{rule_id}': {type(condition)}")
                if match:
                    action_text = str(rule_data["action"])
                    self.logger.debug(f"Rule '{rule_id}' matched. Action: {action_text}")
                    return {"rule": rule_id, "status": "matched", "message": action_text}
            except Exception as e:
                self.logger.error(f"Evaluation error for rule '{rule_id}': {str(e)}")
        self.logger.debug("No rules matched.")
        return None
def generate_sample_config(config_path: str) -> Dict[str, Any]:
    config = {
        "user_active": {
            "condition": {"age": 18},
            "action": "Grant access"
        },
        "high_value_purchase": {
            "condition": ["amount > 500", "category == 'electronics'"],
            "action": "Flag for review"
        }
    }
    with open(config_path, 'w', encoding='utf-8') as f:
        json.dump(config, f, indent=4)
if __name__ == '__main__':
    config_file = "rules_config.json"
    try:
        generate_sample_config(config_file)
        engine = RuleEngine(config_file)
        test_data_1 = {"age": 25, "amount": 300}
        result_1 = engine.evaluate(test_data_1)
        if not result_1:
            print("No match found for Test Data 1")
        else:
            print(f"Result: {result_1}")
    except Exception as e:
        logging.critical(f"Fatal error in execution: {str(e)}")

import json
import logging
from pathlib import Path
from typing import Dict, Any, List, Callable
from dataclasses import dataclass, field
@dataclass
class Rule:
    condition: str = ""
    action: str = ""
    priority: int = 0
    def __post_init__(self):
        if not isinstance(self.condition, str) or self.condition.strip() == "":
            raise ValueError("Condition must be a non-empty string")
        if not isinstance(self.action, str) or self.action.strip() == "":
            raise ValueError("Action must be a non-empty string")
class RuleEngine:
    def __init__(self):
        self.rules: List[Rule] = []
        self.logger = logging.getLogger(__name__)
    def load_rules_from_file(self, file_path: str) -> int:
        try:
            with open(file_path, 'r') as f:
                config_data = json.load(f)
            if not isinstance(config_data, list):
                raise ValueError("Configuration must be a JSON array")
            loaded_count = 0
            for item in config_data:
                try:
                    rule = Rule(
                        condition=item.get('condition', ''),
                        action=item.get('action', ''),
                        priority=int(item.get('priority', 99)) if isinstance(item.get('priority'), str) else int(item['priority'])
                    )
                    self.rules.append(rule)
                    loaded_count += 1
                except (ValueError, TypeError):
                    self.logger.error(f"Failed to parse rule at index {config_data.index(item)}: {item}")
            return loaded_count
        except FileNotFoundError:
            raise ValueError(f"Configuration file not found: {file_path}")
    def sort_rules(self) -> None:
        if len(self.rules) > 1:
            self.rules.sort(key=lambda r: -r.priority)
            self.logger.info("Rules sorted by priority (descending)")
    def evaluate_condition(self, condition_str: str, data: Dict[str, Any]) -> bool:
        try:
            if "==" in condition_str or ">=" in condition_str or "<" in condition_str:
                parts = condition_str.split()
                value_to_check = float(data.get(parts[1], 0))
                op_map = {'>': '>', '<': '<', '>=': '>='}
                operator = op_map.get(parts[-2]) if len(parts) > 2 else '='
                target_value = parts[-1]
                return eval(f"{value_to_check} {operator} {target_value}")
            elif "in" in condition_str.lower():
                items = [x.strip() for x in condition_str.split(' or ')]
                if any(item in data.keys() and True for item in items):
                    return True
        except Exception as e:
            self.logger.error(f"Evaluation error for '{condition_str}': {e}")
        return False
    def execute(self, input_data: Dict[str, Any]) -> List[Dict[str, str]]:
        results = []
        if not self.rules:
            self.logger.warning("No rules loaded. Please load a configuration file first.")
            return results
        for rule in self.rules:
            if self.evaluate_condition(rule.condition, input_data):
                action_result = {
                    "rule": rule.action,
                    "priority": rule.priority,
                    "status": "executed"
                }
                if "log" in rule.action.lower():
                    self.logger.info(f"Executing: {rule.action}")
                results.append(action_result)
        return results
