def filter_groups(data):
    filtered = []
    for group in data:
        numeric_values = [float(x) for x in group if isinstance(x, (int, float))]
        if len(numeric_values) > 0 and all(v == numeric_values[0] for v in numeric_values):
            filtered.append(group)
    return filtered
